//! Bundled website icons of popular sites for the mobile apps
//! (`packages/site-icons/mobile/site-icons-64.pbic`, generated by
//! `scripts/update-site-icons.mjs`).
//!
//! The apps load the pack from their bundle once at start and hand it over
//! with [`set_bundled_site_icons`]. [`Client::icon`](crate::Client::icon)
//! then answers bundled sites from it, without a request, and never asks the
//! server for them (docs/architecture/item-extras.md#website-icons).
//!
//! Pack format (little endian), version 1:
//!
//! ```text
//! "PBIC" | u8 version | u8 size (px) | u16 0 | u32 count | u32 data offset
//! count × ( u8 domain length | domain (ASCII) | u32 offset | u32 length ), sorted by domain
//! image data (one WebP per icon), offsets relative to the data offset
//! ```

use std::sync::{Arc, RwLock};

use crate::{Error, Result};

/// A parsed pack of single icons.
#[derive(Debug)]
pub struct SiteIconPack {
    size: u8,
    bytes: Vec<u8>,
    /// Domain, start and end of its image in `bytes`, sorted by domain.
    entries: Vec<(String, usize, usize)>,
}

fn corrupt() -> Error {
    Error::InvalidData("not a valid website icon pack".into())
}

fn u32_at(bytes: &[u8], at: usize) -> Result<usize> {
    let value: [u8; 4] = bytes
        .get(at..at + 4)
        .and_then(|b| b.try_into().ok())
        .ok_or_else(corrupt)?;
    usize::try_from(u32::from_le_bytes(value)).map_err(|_| corrupt())
}

impl SiteIconPack {
    /// Reads a pack. Fails for anything that is not a version 1 pack.
    pub fn parse(bytes: Vec<u8>) -> Result<Self> {
        if bytes.len() < 16 || &bytes[..4] != b"PBIC" || bytes[4] != 1 {
            return Err(corrupt());
        }
        let size = bytes[5];
        let count = u32_at(&bytes, 8)?;
        let data = u32_at(&bytes, 12)?;
        if data > bytes.len() || count > bytes.len() {
            return Err(corrupt());
        }
        let mut entries = Vec::with_capacity(count);
        let mut at = 16;
        for _ in 0..count {
            let length = usize::from(*bytes.get(at).ok_or_else(corrupt)?);
            let name = bytes.get(at + 1..at + 1 + length).ok_or_else(corrupt)?;
            let domain = std::str::from_utf8(name)
                .ok()
                .filter(|d| d.is_ascii())
                .ok_or_else(corrupt)?
                .to_owned();
            at += 1 + length;
            let start = data.checked_add(u32_at(&bytes, at)?).ok_or_else(corrupt)?;
            let end = start
                .checked_add(u32_at(&bytes, at + 4)?)
                .ok_or_else(corrupt)?;
            if at + 8 > data || end > bytes.len() {
                return Err(corrupt());
            }
            at += 8;
            entries.push((domain, start, end));
        }
        entries.sort_by(|a, b| a.0.cmp(&b.0));
        Ok(Self {
            size,
            bytes,
            entries,
        })
    }

    /// Icon size in pixels.
    pub fn size(&self) -> u8 {
        self.size
    }

    /// Number of bundled sites.
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// The icon (WebP) of `host`: the host itself or, for `www.` hosts, the
    /// name without it. Other subdomains are different sites.
    pub fn get(&self, host: &str) -> Option<&[u8]> {
        let host = host.trim().trim_end_matches('.').to_ascii_lowercase();
        let bare = host.strip_prefix("www.");
        [Some(host.as_str()), bare]
            .into_iter()
            .flatten()
            .find_map(|key| {
                self.entries
                    .binary_search_by(|(domain, _, _)| domain.as_str().cmp(key))
                    .ok()
                    .map(|i| {
                        let (_, start, end) = &self.entries[i];
                        &self.bytes[*start..*end]
                    })
            })
    }

    /// Whether `host` has a bundled icon.
    pub fn contains(&self, host: &str) -> bool {
        self.get(host).is_some()
    }
}

static BUNDLED: RwLock<Option<Arc<SiteIconPack>>> = RwLock::new(None);

/// Installs the bundled icons for every client of this process (`None`
/// removes them). Returns the number of sites.
pub fn set_bundled_site_icons(pack: Option<SiteIconPack>) -> usize {
    let count = pack.as_ref().map_or(0, SiteIconPack::len);
    *BUNDLED.write().unwrap_or_else(|e| e.into_inner()) = pack.map(Arc::new);
    count
}

/// The bundled icons, if the app installed them.
pub fn bundled_site_icons() -> Option<Arc<SiteIconPack>> {
    BUNDLED.read().unwrap_or_else(|e| e.into_inner()).clone()
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;

    /// A pack in the format the generator writes.
    pub(crate) fn pack(icons: &[(&str, &[u8])]) -> Vec<u8> {
        let mut sorted = icons.to_vec();
        sorted.sort_by_key(|(domain, _)| *domain);
        let index: usize = sorted.iter().map(|(d, _)| 1 + d.len() + 8).sum();
        let mut out = b"PBIC\x01\x40\0\0".to_vec();
        out.extend_from_slice(&u32::try_from(sorted.len()).unwrap().to_le_bytes());
        out.extend_from_slice(&u32::try_from(16 + index).unwrap().to_le_bytes());
        let mut offset = 0u32;
        for (domain, image) in &sorted {
            out.push(u8::try_from(domain.len()).unwrap());
            out.extend_from_slice(domain.as_bytes());
            out.extend_from_slice(&offset.to_le_bytes());
            let length = u32::try_from(image.len()).unwrap();
            out.extend_from_slice(&length.to_le_bytes());
            offset += length;
        }
        for (_, image) in &sorted {
            out.extend_from_slice(image);
        }
        out
    }

    #[test]
    fn finds_icons_by_host_and_www() {
        let pack = SiteIconPack::parse(pack(&[
            ("netflix.com", b"RIFFnetflix"),
            ("github.com", b"RIFFgithub"),
        ]))
        .unwrap();
        assert_eq!((pack.len(), pack.size()), (2, 64));
        assert_eq!(pack.get("netflix.com"), Some(&b"RIFFnetflix"[..]));
        assert_eq!(pack.get("WWW.Netflix.com."), Some(&b"RIFFnetflix"[..]));
        assert_eq!(pack.get("github.com"), Some(&b"RIFFgithub"[..]));
        assert_eq!(pack.get("gist.github.com"), None);
        assert_eq!(pack.get("example.com"), None);
        assert!(!pack.contains(""));
    }

    #[test]
    fn refuses_corrupt_packs() {
        assert!(SiteIconPack::parse(b"PBIA\x01\x20".to_vec()).is_err());
        assert!(SiteIconPack::parse(Vec::new()).is_err());
        let mut truncated = pack(&[("netflix.com", b"RIFFnetflix")]);
        truncated.truncate(truncated.len() - 3);
        assert!(SiteIconPack::parse(truncated).is_err());
        let mut lying = pack(&[("netflix.com", b"RIFFnetflix")]);
        lying[8] = 200;
        assert!(SiteIconPack::parse(lying).is_err());
    }

    #[test]
    fn reads_the_committed_mobile_pack() {
        let path = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../packages/site-icons/mobile/site-icons-64.pbic"
        );
        let pack = SiteIconPack::parse(std::fs::read(path).unwrap()).unwrap();
        assert!(!pack.is_empty());
        assert_eq!(pack.size(), 64);
        for (domain, start, end) in &pack.entries {
            let image = &pack.bytes[*start..*end];
            assert!(
                image.starts_with(b"RIFF") && &image[8..12] == b"WEBP",
                "{domain}"
            );
        }
    }
}
